package com.bookeat.dining.controller;
import com.bookeat.common.response.*;import com.bookeat.security.AppPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import lombok.RequiredArgsConstructor;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.*;
@RestController @RequiredArgsConstructor @SecurityRequirement(name="bearerAuth")
public class DiningController {
private final com.bookeat.dining.service.DiningService service;
 @PostMapping("/api/v1/customer/reservations/{id}/check-in/gps") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Check in by GPS",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op0(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.dining.dto.DiningRequests.Gps q){return ApiResponse.ok("Check in by GPS",service.gps(p.userId(),id,q));}
 @PostMapping("/api/v1/customer/reservations/{id}/check-in/qr") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Check in by QR",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op1(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.dining.dto.DiningRequests.Qr q){return ApiResponse.ok("Check in by QR",service.qr(p.userId(),id,q));}
 @PostMapping("/api/v1/owner/restaurants/{restaurantId}/reservations/{id}/manual-check-in") @PreAuthorize("hasRole('OWNER') and hasAuthority('DINING_MANAGE')") @Operation(summary="Record manual reservation check-in",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op2(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id,@Valid @RequestBody com.bookeat.dining.dto.DiningRequests.Action q){return ApiResponse.ok("Record manual reservation check-in",service.manual(p.userId(),restaurantId,id,q));}
 @PostMapping("/api/v1/owner/restaurants/{restaurantId}/reservations/{id}/check-in-token") @PreAuthorize("hasRole('OWNER') and hasAuthority('DINING_MANAGE')") @Operation(summary="Issue a five-minute single-use check-in QR token",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.service.DiningService.CheckinToken> op3(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id){return ApiResponse.ok("Issue a five-minute single-use check-in QR token",service.issue(p.userId(),restaurantId,id));}
 @GetMapping("/api/v1/customer/dining-sessions/current") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load current dining sessions",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<List<com.bookeat.dining.dto.DiningResponse>> op4(@AuthenticationPrincipal AppPrincipal p){return ApiResponse.ok("Load current dining sessions",service.current(p.userId()));}
 @GetMapping("/api/v1/customer/dining-sessions/{id}") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load own dining session",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op5(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){return ApiResponse.ok("Load own dining session",service.get(p.userId(),id));}
 @GetMapping("/api/v1/owner/restaurants/{restaurantId}/dining-sessions") @PreAuthorize("hasRole('OWNER') and hasAuthority('DINING_MANAGE')") @Operation(summary="List restaurant dining sessions",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.dining.dto.DiningResponse>> op6(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List restaurant dining sessions",service.ownerList(p.userId(),restaurantId,page,size));}
 @PutMapping("/api/v1/owner/restaurants/{restaurantId}/dining-sessions/{id}/start") @PreAuthorize("hasRole('OWNER') and hasAuthority('DINING_MANAGE')") @Operation(summary="Dining start",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op7(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id,@Valid @RequestBody com.bookeat.dining.dto.DiningRequests.Action q){return ApiResponse.ok("Dining start",service.action(p.userId(),restaurantId,id,q,"start"));}
 @PutMapping("/api/v1/owner/restaurants/{restaurantId}/dining-sessions/{id}/request-payment") @PreAuthorize("hasRole('OWNER') and hasAuthority('DINING_MANAGE')") @Operation(summary="Dining request-payment",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op8(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id,@Valid @RequestBody com.bookeat.dining.dto.DiningRequests.Action q){return ApiResponse.ok("Dining request-payment",service.action(p.userId(),restaurantId,id,q,"request-payment"));}
 @PutMapping("/api/v1/owner/restaurants/{restaurantId}/dining-sessions/{id}/checkout") @PreAuthorize("hasRole('OWNER') and hasAuthority('DINING_MANAGE')") @Operation(summary="Dining checkout",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.dining.dto.DiningResponse> op9(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id,@Valid @RequestBody com.bookeat.dining.dto.DiningRequests.Action q){return ApiResponse.ok("Dining checkout",service.action(p.userId(),restaurantId,id,q,"checkout"));}
}
